","description":"What a partial decryption decrypts: the sealed cast at a board leaf, or the total of one option of one question.","type":"object","additionalProperties":false,"required":["ciphertext"],"properties":{"leafIndex":{"type":"integer","minimum":0,"description":"A sealed cast\'s board leaf."},"question":{"\$ref":"#/\$defs/Key"},"option":{"\$ref":"#/\$defs/Key"},"ciphertext":{"\$ref":"#/\$defs/ElGamalCiphertext"}},"oneOf":[{"required":["leafIndex"]},{"required":["question","option"]}]},"ElGamalCiphertext":{"title":"ElGamalCiphertext","description":"`(a, b) = (r·G, M + r·Y)` under the election key `Y` (CONVENTIONS §9.2).","type":"object","additionalProperties":false,"required":["a","b"],"properties":{"a":{"\$ref":"#/\$defs/GroupElement"},"b":{"\$ref":"#/\$defs/GroupElement"}}},"Key":{"title":"Key","description":"A question or option key, unique within its manifest or question.","type":"string","pattern":"^[A-Za-z0-9._-]{1,64}\$"},"TrusteeIndex":{"title":"TrusteeIndex","description":"A trustee\'s index: its position in the manifest\'s `trustees.dids`, counting from 1.","type":"integer","minimum":1,"maximum":64}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
